import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { setTimeout } from 'node:timers/promises'

async function writeGeneratedFile(file, content) {
  try {
    if ((await readFile(file, 'utf8')) === content) return
  } catch (error) {
    if (error.code !== 'ENOENT') throw error
  }
  for (let attempt = 0; ; attempt++) {
    try {
      await writeFile(file, content)
      return
    } catch (error) {
      // Windows can temporarily deny opening generated files while another process reads them.
      const transient =
        process.platform === 'win32' && ['UNKNOWN', 'EBUSY', 'EPERM', 'EACCES'].includes(error.code)
      if (!transient || attempt >= 4) throw error
      await setTimeout(50 * 2 ** attempt)
    }
  }
}

const previewRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const root = resolve(previewRoot, '../../../packages/@fex-design/components/angular')
const entries = []
for (const layer of ['primitive', 'ui'])
  for (const component of await readdir(resolve(root, 'src', layer), { withFileTypes: true })) {
    if (!component.isDirectory() || component.name.toLowerCase().includes('trash')) continue
    try {
      for (const file of await readdir(resolve(root, 'src', layer, component.name, 'examples'), {
        withFileTypes: true,
      })) {
        if (!file.isFile() || !file.name.endsWith('.ts')) continue
        const source = resolve(root, 'src', layer, component.name, 'examples', file.name)
        const content = await readFile(source, 'utf8')
        const exported =
          content.match(/export class (\w+)/)?.[1] ?? content.match(/export \{ (\w+) \} from/)?.[1]
        if (exported)
          entries.push({
            key: `${layer}/${component.name}/${file.name.slice(0, -3)}`,
            exported,
            source,
          })
      }
    } catch {}
  }
entries.sort((a, b) => a.key.localeCompare(b.key))
const loaders = entries.map((entry) => {
  const path = relative(resolve(previewRoot, 'src'), entry.source)
    .split(sep)
    .join('/')
    .replace(/\.ts$/, '')
  const specifier = path.startsWith('.') ? path : './' + path
  return (
    "  '" +
    entry.key +
    "': () => import('" +
    specifier +
    "').then((module) => module." +
    entry.exported +
    '),'
  )
})
const output = resolve(previewRoot, 'src/examples.generated.ts')
await mkdir(dirname(output), { recursive: true })
// Keep generated source files below the repository's 300-line limit as examples grow.
const chunks = []
for (let offset = 0; offset < loaders.length; offset += 200) {
  const index = chunks.length
  const file = `examples.generated-${index}.ts`
  chunks.push(file)
  await writeGeneratedFile(
    resolve(previewRoot, 'src', file),
    `// Generated by scripts/generate-examples.mjs. Do not edit.\nimport type { Type } from '@angular/core'\n\nexport const examples: Record<string, () => Promise<Type<unknown>>> = {\n${loaders.slice(offset, offset + 200).join('\n')}\n}\n`,
  )
}
await writeGeneratedFile(
  output,
  `// Generated by scripts/generate-examples.mjs. Do not edit.\n${chunks.map((file, index) => `import { examples as examples${index} } from './${file.slice(0, -3)}'`).join('\n')}\n\nexport const examples = {\n${chunks.map((_, index) => `  ...examples${index},`).join('\n')}\n}\n`,
)
